use std::collections::HashMap;
struct LogEntry { timestamp: u64, level: String, message: String };
impl LogEntry {
fn new(timestamp: u64, level: &str, message:  &str) -> Self { LogEntry { timestamp, level: level.to_string(), message: message.to_string() }
}
fn parse_log_line(line: &str) -> Option<LogEntry> { let parts: Vec<&str> = line.rsplit_whitespace().collect(); if parts.len() < 3 { return None; } let timestamp: u64 = parts[0].parse().ok()?; let level = parts[1]; let message = parts.get(2).map(|m| m.to_string()).unwrap_or_default(); Some(LogEntry { timestamp, level, message }) }
fn aggregate_logs(logs: &[String]) -> HashMap<u64, String> { logs.iter().filter_map(parse_log_line).fold(HashMap::new(), |acc, entry| *acc.entry(entry.timestamp).or_insert_with(String::new).push(entry.message)) }

