from typing import List, Dict, Optional

class TaskManager:
    def __init__(self):
        self.tasks: List[Dict[str, str]] = []

    def add_task(self, title: str) -> int:
        """添加任务，返回新任务 ID"""
        if not title or len(title.strip()) == 0:
            return -1
        self.tasks.append({'id': len(self.tasks), 'title': title})
        return len(self.tasks) - 1

    def get_tasks(self) -> List[Dict[str, str]]:
        """获取所有任务"""
        return self.tasks.copy()

    def update_task(self, task_id: int, title: str) -> bool:
        """更新指定 ID 的任务标题"""
        for t in self.tasks:
            if t['id'] == task_id:
                t['title'] = title.strip()
                return True
        return False

    def delete_task(self, task_id: int) -> bool:
        """删除指定 ID 的任务"""
        for i, t in enumerate(self.tasks):
            if t['id'] == task_id:
                del self.tasks[i]
                return True
        return False

    def get_task_by_id(self, task_id: int) -> Optional[Dict[str, str]]:
        """按 ID 获取任务"""
        for t in self.tasks:
            if t['id'] == task_id:
                return t
        return None

use std::fs;
use std::io;
use std::path::Path;

struct Worker  { 
    output_file: String,
} 

impl Worker  { 
    fn new(output_file: String)  -> Self  { 
        Worker  { output_file   }
      } 

    fn run(&self)  -> Result<(), Box<dyn std::error::Error>>  { 
        let mut file  = match fs::File::create(&self.output_file)  { 
            Ok(f)  => f, 
            Err(_)  => return Err("Failed to create output file".into()),
         }; 

        let mut writer  = io::BufWriter::new(file); 
        writeln!(writer,  "Worker started").map_err(|e| e.into())?; 

         // 处理进程被杀的情况：先写临时文件再原子改名
        let temp_file   = format!("{}.tmp", self.output_file); 
        let mut temp_writer   = io::BufWriter::new(io::File::create(&temp_file).unwrap()); 
        writeln!(temp_writer,  "Worker started  (killed)").map_err(|e| e.into())?; 

         // 原子改名：先 rename to temp，再 rename 到最终路径
        match fs::rename(&mut temp_file,  &self.output_file)  { 
            Ok(_)  => writer.try_flush().map_err(|e| e.into())?,
            Err(e)  => return Err(format!("Failed to atomically rename: {}", e).into()),
          } 

         // 写入实际内容（worker 运行期间的输出）
        writeln!(writer,  "Worker running").map_err(|e| e.into())?; 

        Ok(())
      }
}

