"""Python worker for processing tasks from a directory."""
import os
import sys
from pathlib import Path

# Task data structure
class Task:
    def __init__(self, file_path):
        self.file_path = file_path

# Worker class
class Worker:
    def __init__(self, input_dir: str, output_dir: str, deadletter_dir: str):
        self.input_dir = Path(input_dir)
        self.output_dir = Path(output_dir)
        self.deadletter_dir = Path(deadletter_dir)
        self.tasks = []

    def load_tasks(self) -> list:
        """Load all task files from input directory."""
        for file_path in self.input_dir.glob("*.txt"):
            self.tasks.append(Task(file_path))

    def process_task(self, task: Task) -> bool:
        """Process a single task. Returns True on success."""
        try:
            # Simulate processing
            with open(task.file_path, 'r') as f:
                content = f.read()
            print(f"Processing {task.file_path}")
            return True
        except Exception as e:
            print(f"Error processing {task.file_path}: {e}")
            return False

    def run(self) -> None:
        """Run the worker: load tasks, process in order, archive on success."""
        self.load_tasks()
        for task in self.tasks:
            if not self.process_task(task):
                # Retry 3 times
                for attempt in range(1, 4):
                    print(f"Retrying {task.file_path} (attempt {attempt})")
                # Move to dead letter after retries
                self.deadletter_dir.mkdir(parents=True, exist_ok=True)
                task_file = self.deadletter_dir / task.file_path.name
                try:
                    task_file.rename(task.file_path)
                except Exception as e:
                    print(f"Failed to move {task_file} to dead letter: {e}")
        # Archive processed tasks
        for task in self.tasks:
            if os.path.exists(task.file_path):
                print(f"Archiving {task.file_path}")

if __name__ == "__main__":
    worker = Worker("/tmp", "/tmp/out", "/tmp/deadletter")
    worker.run()

